def test_fuzzy_terms_support_messy_wording():
    match = analyze("Spool errected for Line 247-XX near compressor area")["match"]
    assert match["recommendedMatchId"] == PIPING["id"]
    assert "Identifier matched" in match["matchReason"]


def test_other_projects_and_schedule_levels_are_excluded():
    match = analyze("Spool erected for Line 247-XX", [{**PIPING, "projectId": "OTHER-PROJECT"}, {**PIPING, "id": "OTHER-LEVEL", "level": "L4"}])["match"]
    assert match["candidates"] == []


def test_deterministic_order_independent_versioned_and_timestamped():
    schedules = [PIPING, {**PIPING, "id": "TEST-SECOND", "activityName": "Fit-up Line 247-XX joints"}]
    first = analyze("Spool erected for Line 247-XX", schedules)
    assert first == analyze("Spool erected for Line 247-XX", schedules[::-1])
    assert first["match"]["matcherVersion"] == MATCHER_VERSION
    assert first["match"]["generatedAt"] == NOW


def test_confidence_bands_and_javascript_rounding():
    assert [confidence_level(score) for score in (0, 59, 60, 79, 80, 100)] == ["low", "low", "medium", "medium", "high", "high"]
    signals = {key: {"available": True, "similarity": 0} for key in ("activity", "identifier", "discipline", "location", "keywords")}
    signals["activity"]["similarity"] = .6125
    assert calculate_confidence(signals)["score"] == 25


def test_submission_has_no_approval_or_actual_contribution_and_matches_js():
    result = submit()
    assert_golden(result, GOLDEN["submitted"])
    match = match_for(result)
    assert match["matchStatus"] == "review_required"
    assert match["matchedBy"] is None
    assert result["scheduleActivityContributions"] == GOLDEN["seed"]["scheduleActivityContributions"]
    assert result["fieldUpdates"][0]["reviewHistory"][1]["actorUserId"] is None


def test_confirm_change_unmatch_reconfirm_preserve_intelligence_and_reconcile():
    result = submit()
    initial_match = deepcopy(match_for(result))
    result = workflow.confirm_match(result, {**GOLDEN["opts"], "scheduleActivityId": "SA-1024"})
    assert_golden(result, GOLDEN["confirmed"])
    assert schedule_for(result["data"], "SA-1024")["progress"] == 40
    result = workflow.change_match(result["data"], {**GOLDEN["opts"], "scheduleActivityId": "SA-1031"})
    assert_golden(result, GOLDEN["changed"])
    assert schedule_for(result["data"], "SA-1024")["progress"] == 65
    assert schedule_for(result["data"], "SA-1031")["progress"] == 40
    result = workflow.mark_unmatched(result["data"], {**GOLDEN["opts"], "reason": "Wrong scope", "feedback": "Please check"})
    assert_golden(result, GOLDEN["unmatched"])
    assert schedule_for(result["data"], "SA-1031")["progress"] == result["data"]["scheduleActivityBaselines"]["SA-1031"]["progress"]
    assert not any(item["fieldUpdateId"] == "TEST-UPDATE" for item in result["data"]["scheduleActivityContributions"])
    result = workflow.confirm_match(result["data"], {**GOLDEN["opts"], "scheduleActivityId": "SA-1031"})
    assert_golden(result, GOLDEN["reconfirmed"])
    match = match_for(result["data"])
    assert match["candidates"] == initial_match["candidates"]
    assert match["matchedByUserId"] == "PM-001"
    assert any(item["fieldUpdateId"] == "FU-1042" for item in result["data"]["scheduleActivityContributions"])


def test_edit_rematches_resets_review_and_preserves_unrelated_contributions():
    result = workflow.rematch_field_update(GOLDEN["editedInput"], "TEST-UPDATE", GOLDEN["rematchContext"])
    assert_golden(result, GOLDEN["rematched"])
    match = match_for(result["data"])
    assert match["recommendedMatchId"] == "SA-1031"
    assert match["matchedByUserId"] is None
    assert match["generatedAt"] == "2026-10-04T09:00:00.000Z"
    update = next(item for item in result["data"]["fieldUpdates"] if item["id"] == "TEST-UPDATE")
    assert update["reviewHistory"][-1]["actorUserId"] == "TL-001"
    assert result["data"]["scheduleActivityContributions"] == GOLDEN["seed"]["scheduleActivityContributions"]


