def test_mutators_never_modify_caller_input():
    original = deepcopy(GOLDEN["seed"])
    submitted = submit()
    workflow.confirm_match(submitted, {**GOLDEN["opts"], "scheduleActivityId": "SA-1024"})
    for case in GOLDEN["actions"]:
        workflow.record_activity_action(GOLDEN["seed"], case["options"])
    assert GOLDEN["seed"] == original
    assert_golden(submitted, GOLDEN["submitted"])


def test_invalid_completed_and_cross_project_reviews_fail_without_changes():
    result = submit()
    invalid = workflow.confirm_match(result, {**GOLDEN["opts"], "scheduleActivityId": "MISSING"})
    assert invalid["error"] == "The selected schedule activity could not be found."
    result["scheduleActivities"].append({**PIPING, "id": "OTHER-PROJECT-ACTIVITY"})
    invalid = workflow.confirm_match(result, {**GOLDEN["opts"], "scheduleActivityId": "OTHER-PROJECT-ACTIVITY"})
    assert invalid["error"] == "The selected schedule activity belongs to a different project."
    result["fieldUpdates"][0]["progress"] = 100
    invalid = workflow.confirm_match(result, {**GOLDEN["opts"], "scheduleActivityId": "SA-1024"})
    assert invalid["error"] == "Actual completion time is required before confirming this update."
    assert invalid["data"] == result


def test_review_uuid_uniqueness_and_request_review_idempotence():
    first, second = submit(), submit()
    assert first["reviewItems"][0]["id"] != second["reviewItems"][0]["id"]
    assert re.fullmatch(r"REV-[0-9a-f-]{36}", first["reviewItems"][0]["id"])
    requested = workflow.request_planner_review(first, "TEST-UPDATE", {"reviewer": "Priya", "reviewerUserId": "PM-001"})
    assert requested == first


def test_legacy_enrichment_preserves_decisions_history_baseline_and_actuals():
    seed = GOLDEN["seed"]
    result = workflow.enrich_match_intelligence(seed, NOW)
    assert result == seed
    assert result is not seed


def test_invalid_submission_and_action_inputs_do_not_change_workspace():
    for progress in (-1, 101, float("nan"), True, "20"):
        assert workflow.submit_field_update(GOLDEN["seed"], {"description": "Spool erected", "progress": progress}, GOLDEN["context"]) == GOLDEN["seed"]
    assert workflow.submit_field_update(GOLDEN["seed"], {"description": " ", "progress": 40}, GOLDEN["context"]) == GOLDEN["seed"]
    assert workflow.block_activity(GOLDEN["seed"], {"activityId": "TL-2002", "details": {"blockedReason": " "}}) == GOLDEN["seed"]
